/* Copy sections via .copy.table (SDK-style).
 * Each entry: [source_addr, dest_addr, size_in_bytes]
 * This copies .data AND .retm_data (retention RAM) from flash.
 */

const uint32_t *table = &__copy_table_start__;
const uint32_t *table_end = &__copy_table_end__;

while (table < table_end)
  {
    const uint32_t *t_src  = (const uint32_t *)table[0];
    uint32_t       *t_dest = (uint32_t *)table[1];
    uint32_t        t_size = table[2] / 4;  /* convert bytes to words */

    for (uint32_t i = 0; i < t_size; i++)
      {
        *t_dest++ = *t_src++;
      }

    table += 3;
  }

/* Zero sections via .zero.table.
 * Each entry: [dest_addr, size_in_bytes]
 */

const uint32_t *ztable = &__zero_table_start__;
const uint32_t *ztable_end = &__zero_table_end__;

while (ztable < ztable_end)
  {
    uint32_t *z_dest = (uint32_t *)ztable[0];
    uint32_t  z_size = ztable[1] / 4;  /* convert bytes to words */

    for (uint32_t i = 0; i < z_size; i++)
      {
        *z_dest++ = 0;
      }

    ztable += 2;
