/* Copy sections via .copy.table (CMSIS __cmsis_start pattern).
 * Each entry: {src, dest, wlen} — wlen is word count.
 * This copies .data AND .retm_data (retention RAM) from flash.
 */

for (__copy_table_t const *pTable = &__copy_table_start__;
     pTable < &__copy_table_end__; ++pTable)
  {
    for (uint32_t i = 0u; i < pTable->wlen; ++i)
      {
        pTable->dest[i] = pTable->src[i];
      }
  }

/* Zero sections via .zero.table.
 * Each entry: {dest, wlen} — wlen is word count.
 */

for (__zero_table_t const *pTable = &__zero_table_start__;
     pTable < &__zero_table_end__; ++pTable)
  {
    for (uint32_t i = 0u; i < pTable->wlen; ++i)
      {
        pTable->dest[i] = 0u;
      }
  }

